async function searchCompaniesInMemory(query, limit = 5) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'searchCompanies',
        query: query,
        limit: limit
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to search companies');
    }

    return {
      success: true,
      companies: result.results,
      totalFound: result.results.length,
      query: query,
      message: `Found ${result.results.length} companies matching '${query}'`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
